const express = require('express');
const crypto = require('crypto');
const { AuditLogService, TenantDomainRegistry } = require('../services/audit');

const app = express();
app.use(express.json());

app.post('/api/webhooks/auth0/password-changed', async (req, res) => {
  // Validate Auth0 HMAC signature
  const signature = req.headers['x-auth0-signature'];
  const expectedSig = crypto
    .createHmac('sha256', process.env.AUTH0_AUDIT_WEBHOOK_SECRET)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (!signature || signature !== expectedSig) {
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  const { userId, tenantDomain } = req.body;

  // Verify that target user belongs to the specified tenant domain
  const isMember = await TenantDomainRegistry.isUserInDomain(userId, tenantDomain);
  if (!isMember) {
    return res.status(403).json({ error: 'Access denied: user not associated with tenant domain' });
  }

  const auditEntries = await AuditLogService.getSecurityHistoryForUser(userId);

  res.json({
    userId,
    tenantDomain,
    recentLogins: auditEntries
  });
});

app.listen(9005);
